<?php require '../config/database.php';auth();$products=$pdo->query('SELECT * FROM products WHERE quantity>0 ORDER BY name')->fetchAll();$customers=$pdo->query('SELECT id,name FROM customers ORDER BY name')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$pid=(int)$_POST['product_id'];$qty=(int)$_POST['quantity'];$s=$pdo->prepare('SELECT * FROM products WHERE id=? FOR UPDATE');$pdo->beginTransaction();try{$s->execute([$pid]);$p=$s->fetch();if(!$p||$qty<1||$p['quantity']<$qty)throw new Exception('الكمية غير متوفرة');$total=$p['sale_price']*$qty;$paid=(float)$_POST['paid'];if($paid>$total)$paid=$total;$ins=$pdo->prepare('INSERT INTO sales(customer_id,user_id,total,paid,remaining,payment_method) VALUES(?,?,?,?,?,?)');$ins->execute([$_POST['customer_id']?:null,$_SESSION['user_id'],$total,$paid,$total-$paid,$_POST['payment_method']]);$saleId=$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,quantity,price,total) VALUES(?,?,?,?,?)');$ins->execute([$saleId,$pid,$qty,$p['sale_price'],$total]);$up=$pdo->prepare('UPDATE products SET quantity=quantity-? WHERE id=?');$up->execute([$qty,$pid]);if($paid>0){$pay=$pdo->prepare('INSERT INTO payments(customer_id,sale_id,amount,payment_method,notes) VALUES(?,?,?,?,?)');$pay->execute([$_POST['customer_id']?:null,$saleId,$paid,$_POST['payment_method'],'دفعة مبيعات']);}$pdo->commit();header('Location:index.php');exit;}catch(Throwable $e){$pdo->rollBack();$error=$e->getMessage();}}?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>عملية بيع</h1><?php if(isset($error)):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><label>العميل</label><select name="customer_id"><option value="">نقدي</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select><label>المنتج</label><select name="product_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?> - <?=$p['sale_price']?> (متوفر <?=$p['quantity']?>)</option><?php endforeach;?></select><label>الكمية</label><input type="number" name="quantity" min="1" value="1" required><label>المبلغ المدفوع</label><input type="number" step="0.01" name="paid" value="0"><label>طريقة الدفع</label><select name="payment_method"><option value="cash">نقدي</option><option value="transfer">تحويل</option><option value="card">بطاقة</option></select><button>حفظ البيع</button></form></main>
